  // 在此处编写代码

}

answer:
async function retryFetch(url, maxRetries) {
  let lastError
  for (let i = 0; i <= maxRetries; i++) {
    try {
      const res = await fetch(url)
      if (!res.ok) throw new Error('HTTP ' + res.status)
      return await res.json()
    } catch (err) {
      lastError = err
      if (i < maxRetries) {
        await new Promise(r => setTimeout(r, 500))
      }
    }
  }
  throw lastError
}
